const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Smith Island coordinates (Chesapeake Bay, Maryland/Virginia)
  const smithIsland = ee.Geometry.Point([-75.95, 37.95]).buffer(5000);

  // Define time periods
  const start1999 = '1999-01-01';
  const end1999 = '1999-12-31';
  const start2019 = '2019-01-01';
  const end2019 = '2019-12-31';

  // Function to mask clouds and calculate NDWI
  function maskCloudsAndWater(image) {
    // Cloud masking for Landsat
    const cloudShadowBitMask = 1 << 3;
    const cloudsBitMask = 1 << 5;
    const qa = image.select('QA_PIXEL');
    const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
                 .and(qa.bitwiseAnd(cloudsBitMask).eq(0));

    // Calculate NDWI for water detection
    const ndwi = image.normalizedDifference(['SR_B3', 'SR_B5']).rename('NDWI');

    return image.updateMask(mask).addBands(ndwi);
  }

  // Get Landsat collections
  let landsat1999 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterDate(start1999, end1999)
    .filterBounds(smithIsland);

  let landsat2019 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterDate(start2019, end2019)
    .filterBounds(smithIsland);

  // Check if collections are empty and try fallback
  if (landsat1999.size().getInfo() === 0) {
    landsat1999 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
      .filterDate(start1999, end1999)
      .filterBounds(smithIsland);
  }

  // Process 1999 data
  const processed1999 = landsat1999.map(maskCloudsAndWater);
  const composite1999 = processed1999.median();

  // Process 2019 data  
  const processed2019 = landsat2019.map(maskCloudsAndWater);
  const composite2019 = processed2019.median();

  // Check collection sizes
  const count1999 = landsat1999.size().getInfo();
  const count2019 = landsat2019.size().getInfo();

  console.log(`1999 Images: ${count1999}, 2019 Images: ${count2019}`);

  if (count1999 === 0 || count2019 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Calculate land area (non-water pixels)
  const waterThreshold = 0;

  // Land = NDWI < threshold (negative values)
  const landMask1999 = composite1999.select('NDWI').lt(waterThreshold);
  const landMask2019 = composite2019.select('NDWI').lt(waterThreshold);

  // Count land pixels
  const landArea1999 = landMask1999.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: smithIsland,
    scale: 30,
    maxPixels: 1e9
  }).get('NDWI').getInfo();

  const landArea2019 = landMask2019.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: smithIsland,
    scale: 30,
    maxPixels: 1e9
  }).get('NDWI').getInfo();

  console.log(`1999 Land Pixels: ${Math.round(landArea1999)}`);
  console.log(`2019 Land Pixels: ${Math.round(landArea2019)}`);

  // Check for valid pixels
  if (landArea1999 === 0 || landArea2019 === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Check for calculation failures
  if (landArea1999 === null || landArea2019 === null || 
      isNaN(landArea1999) || isNaN(landArea2019)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Calculate area change
  const areaChange = ((landArea2019 - landArea1999) / landArea1999 * 100);
  console.log(`Area Change: ${areaChange.toFixed(1)}%`);

  // Determine answer
  if (landArea2019 < landArea1999) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
